import type { ReactNode } from 'react'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { AppShell } from '@/components/app-shell/app-shell'

export default async function AppLayout({ children }: { children: ReactNode }) {
  const supabase = await createClient()
  const { data, error } = await supabase.auth.getClaims()

  if (error || !data?.claims?.sub) redirect('/signin')

  return (
    <>
      <a className="skipLink" href="#main-content">Skip to main content</a>
      <AppShell
        user={{
          id: data.claims.sub,
          email: typeof data.claims.email === 'string' ? data.claims.email : undefined,
        }}
      >

'use client'

export default function TasksError({ reset }: { reset: () => void }) {
  return (
    <section role="alert">
      <h2>We could not load tasks</h2>
      <p>The request failed. Try again, or contact support if the problem continues.</p>
      <button type="button" onClick={() => reset()}>Try again</button>
    </section>
  )
}

export default function LoadingTasks() {
  return (
    <section aria-busy="true" aria-live="polite">
      <p>Loading tasks...</p>
    </section>
  )
}

